import{releaseTaskRows as t,workItemRows as e}from"../store/plan.mjs";const a=864e5;export const pxPerDay=40;export const lockedWidth=173;export function planWindow(n){const o=n.getTime()+Math.min(...[...e,...t].map(t=>t.start))*a,r=o-(new Date(o).getUTCDay()+6)%7*a;return{end:new Date(r+3024e6),start:new Date(r)}}export function dayLabel(t,e=!0){return t.toLocaleDateString("en-GB",{day:"numeric",...e&&{month:"short"},timeZone:"UTC"})}export function daysLabel(t,e){const n=Math.floor(t.getTime()/a),o=Math.max(n,Math.floor((e.getTime()-1)/a)),r=new Date(o*a);return o===n?dayLabel(t):t.getUTCMonth()===r.getUTCMonth()?`${dayLabel(t,!1)}–${dayLabel(r)}`:`${dayLabel(t)} – ${dayLabel(r)}`}export function planningAxis(t){return{majorFormatter:t=>dayLabel(t.date),majorTickUnit:"week",minorFormatter:t=>dayLabel(t.date,!1),timeAxis:{...planWindow(t),pxPerMinute:40/1440,snapMinutes:1440,tickUnit:"day",timeZone:"UTC"}}}